head.script:
// 원본 : ULDFIL52100 의무보유주식의 처분 작성화면 (/ui/lst/lstinvstg/ULDFIL52100.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 신규는 기본값만 채우고, 수정·조회는 상세를 조회
 * 2. 「법인명」 옆 돋보기 클릭시 「법인명 찾기」 팝업 호출
 * 3. 「보유내역 찾기」 클릭시 회사를 고른 뒤에만 팝업 호출
 * 4. 「재보유 여부」 체크시 「재보유 일자」 입력칸을 활성화
 * 5. 처분 주식수 입력시 최종 주식수를 자동 계산
 * 6. 「저장」 클릭시 입력값 검증 후 첨부파일과 함께 저장
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDFIL52100";

// 화면 상태값
scwin.loadTp = "";
scwin.aplcNo = "";

// 파일 선택 시 어느 항목의 파일인지 기억한다. 첨부가 한 개뿐이면 지워도 된다.
scwin.uploadTarget = "";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 14
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	try {
		// 초기화 함수
		await scwin.init();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDFIL52100.onpageload" });
	}
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 14
 * @description 초기화. 넘겨받은 파라미터로 모드를 정하고, 신규가 아니면 상세를 조회한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름(aplcNo)
 *  - 달력 컴포넌트 id 목록
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 이전 화면에서 전달받은 파라미터
	const param = $c.data.getParameter();

	scwin.loadTp = param.loadTp ?? "0";
	scwin.aplcNo = param.aplcNo ?? "";

	// 달력 입력 형식 체크 SET. 화면에 있는 inputCalendar 를 모두 넣는다.
	["cal_reopnDd"].forEach(calendarId => {
		$c.date.checkCalendarFormat(calendarId, "yyyyMMdd");
	});

	// 접속정보 표시. 세션에서 읽는다. 화면에서 따로 조회하지 않는다.
	scwin.setUserInfo();

	// 모드에 따라 버튼과 입력 가능 여부를 정한다.
	scwin.setFormMode();

	if (scwin.isNewMode()) {
		// 신규는 조회 없이 기본값만 채운다.
		scwin.setDefaultValue();
		return;
	}

	await scwin.selectDetail();
};

/**
 * @method
 * @name scwin.isNewMode
 * @author Inswave
 * @date 2026. 08. 14
 * @description 신규 모드인지 반환한다. 모드 판정을 함수로 묶어 두면
 * 화면 곳곳에 코드값 비교문이 흩어지지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.isNewMode = function () {
	return scwin.loadTp === "0";
};

/**
 * @method
 * @name scwin.isViewMode
 * @author Inswave
 * @date 2026. 08. 14
 * @description 조회 전용 모드인지 반환한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.isViewMode = function () {
	return scwin.loadTp === "8";
};

/**
 * @method
 * @name scwin.setUserInfo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 접속한 사용자 정보를 화면 위쪽에 표시한다.
 *
 * 로그인 정보는 세션에서 읽는다. 화면에서 별도로 조회하지 않는다.
 * 조회하면 통신이 늘고 값이 세션과 어긋날 수 있다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 표시할 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.setUserInfo = function () {
	const userId = $c.session.getUserInfo("integUsrId");
	const empNm = $c.session.getUserInfo("empNm");

	txt_userInfo.setValue(`${userId} / ${empNm}`);
};

/**
 * @method
 * @name scwin.setReopnInput
 * @author Inswave
 * @date 2026. 08. 18
 * @description 재보유 여부에 따라 일자 입력칸을 열고 닫는다.
 *
 * 닫을 때 값도 함께 비운다. 남겨 두면 보이지 않는 값이 그대로 저장된다.
 * 잠금과 값 비움을 한 곳에 묶어 두면 빠뜨릴 수 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 대상 컴포넌트와 키
 * @param
 * @returns
 * @hidden N
*/
scwin.setReopnInput = function (reopnYn) {
	const isReopn = reopnYn === "Y";

	cal_reopnDd.setDisabled(!isReopn);

	if (!isReopn) dma_detail.set("reopnDd", "");
};

/**
 * @method
 * @name scwin.calcLastShares
 * @author Inswave
 * @date 2026. 08. 18
 * @description 최종 주식수를 계산해 넣는다. 최초에서 처분을 뺀 값이다.
 *
 * 사용자가 직접 넣는 값이 아니라 계산으로 정해진다.
 * 계산식을 화면 곳곳에 흩어 두지 않고 이 함수 한 곳에만 둔다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 계산식
 * @param
 * @returns
 * @hidden N
*/
scwin.calcLastShares = function () {
	const fstShrs = scwin.toNumber(dma_detail.get("fstShrs"));
	const withdShrs = scwin.toNumber(dma_detail.get("withdShrs"));

	dma_detail.set("lstShrs", $c.num.formatNumber(fstShrs - withdShrs));
};

/**
 * @method
 * @name scwin.setFormMode
 * @author Inswave
 * @date 2026. 08. 14
 * @description 모드에 따라 버튼 노출과 입력 가능 여부를 정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 버튼 id 목록, 입력 잠글 컴포넌트 목록
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormMode = function () {
	const isView = scwin.isViewMode();

	// 조회 모드면 저장 버튼을 감춘다.
	scwin.toggle(btn_save, !isView);

	// 조회 모드면 입력을 막는다. 그룹 단위로 거는 편이 컴포넌트를 하나씩 도는 것보다 간단하다.
	grp_form.setReadOnly(isView);
};

/**
 * @method
 * @name scwin.toggle
 * @author Inswave
 * @date 2026. 08. 14
 * @description 컴포넌트 노출 여부를 설정한다. show 는 인자가 필요해 매번 삼항으로 쓰기 번거로워 묶었다.
 * @param
 * @returns
 * @hidden N
*/
scwin.toggle = function (component, isVisible) {
	if (isVisible) {
		component.show("");
	} else {
		component.hide();
	}
};

/**
 * @method
 * @name scwin.setDefaultValue
 * @author Inswave
 * @date 2026. 08. 14
 * @description 신규 작성 시 기본값을 채운다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 기본값을 넣을 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.setDefaultValue = function () {
	// 재보유는 기본이 「아니오」다. 고르면 일자를 입력할 수 있다.
	chk_reopnYn.setValue("N");

	scwin.setReopnInput("N");
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.chk_reopnYn_onviewchange
 * @author Inswave
 * @date 2026. 08. 18
 * @description 재보유 여부 변경. 값에 따라 일자 입력칸을 열고 닫는다.
 *
 * 체크박스(select renderType="checkboxgroup")가 넘기는 값은
 * { checked, value, ... } 다. newValue 는 없다.
 * info.newValue 를 쓰면 undefined 가 들어가 분기가 항상 한쪽으로 쏠린다.
 * 셀렉트박스(select1 appearance="minimal")는 반대로 newValue 를 넘긴다.
 * 컴포넌트마다 다르므로 무엇이 오는지 확인하고 쓴다.
 * @param
 * @returns
 * @hidden N
*/
scwin.chk_reopnYn_onviewchange = function (info) {
	try {
		// 마크업의 trueValue="Y" falseValue="N" 과 같은 값으로 바꿔 넘긴다.
		scwin.setReopnInput(info.checked ? "Y" : "N");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL52100.chk_reopnYn_onviewchange" });
	}
};

/**
 * @event
 * @name scwin.btn_findDetail_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 보유내역 찾기 버튼 클릭. 회사를 고른 뒤에만 열린다.
 *
 * 앞 단계 값이 있어야 뒤 팝업을 열 수 있는 구조다.
 * 열고 나서 조건이 없다고 알리는 것보다 열기 전에 막는 편이 낫다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - openPopup 의 팝업 경로, 넘길 파라미터, 받은 값을 넣을 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_findDetail_onclick = async function (e) {
	try {
		if ($c.util.isEmpty(dma_detail.get("corpCd"))) {
			await $c.win.alert($c.data.getMessage("com_crud_0199", "회사명"));
			return;
		}

		const param = {
			corpCd : dma_detail.get("corpCd"),
			bzProcsNo : dma_detail.get("bzProcsNo")
		};

		const options = {
			id : "ULDFIL52110",
			popupName : "보유내역 찾기",
			width : 900,
			height : 500,
			frameModal : "top",
			type : "pageFramePopup"
		};

		const result = await $c.win.openPopup("/ui/sample/template/ULDFIL52110.xml", options, param);

		// 고르지 않고 닫으면 결과가 없다.
		if ($c.util.isEmpty(result)) return;

		// 고른 내역의 값을 화면에 채운다. 최종 주식수는 계산으로 정해진다.
		dma_detail.set("shrhdNm", result.chrgNm);
		dma_detail.set("objKind", result.comNm);
		dma_detail.set("fstShrs", "1000000");

		scwin.calcLastShares();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDFIL52100.btn_findDetail_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_findCorp_onclick
 * @author Inswave
 * @date 2026. 08. 14
 * @description 회사 찾기 버튼 클릭. 팝업에서 고른 값을 화면에 반영한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 팝업 경로·크기, 넘길 파라미터, 돌려받은 값을 어느 컴포넌트에 넣을지
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_findCorp_onclick = async function (e) {
	try {
		const param = {
			corpNm : ipt_corpNm.getValue()
		};

		const options = {
			id : "ULDFIL52110",
			popupName : "회사 찾기",
			width : 900,
			height : 820,
			frameModal : "top",
			type : "pageFramePopup"
		};

		const result = await $c.win.openPopup("/ui/sample/template/ULDFIL52110.xml", options, param);

		// 선택 없이 닫으면 결과가 없다. 이 확인을 빼면 아래에서 undefined 참조로 터진다.
		if ($c.util.isEmpty(result)) return;

		ipt_corpCd.setValue(result.isurCd);
		ipt_corpNm.setValue(result.comNm);
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDFIL52100.btn_findCorp_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_file_onclick
 * @author Inswave
 * @date 2026. 08. 14
 * @description 파일 선택 버튼 클릭. multiupload 의 파일 선택창을 연다.
 *
 * 첨부 항목이 여러 개면 버튼마다 uploadTarget 을 다르게 넣어 두고,
 * selectCallback 에서 그 값으로 어느 입력칸에 파일명을 넣을지 판단한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_file_onclick = function (e) {
	try {
		// 버튼 id 뒤쪽으로 대상을 가른다. btn_fileDoc -> docFileNm, btn_fileAttach -> attachFileNm
		scwin.uploadTarget = this.getOriginalID() === "btn_fileDoc" ? "docFileNm" : "attachFileNm";

		// 공통 함수가 multiupload 내부 input(엔진이 만든 "컴포넌트id_file_input")을 클릭해
		// 파일 대화상자를 연다. 버튼 onclick 안에서 바로 호출해야 한다.
		// await 뒤로 미루면 브라우저의 사용자 조작 인정이 풀려 대화상자가 열리지 않는다.
		//
		// DOM 요소를 $c.util.isEmpty 로 검사하면 안 된다.
		// 내부적으로 Object.keys 길이를 세는데 DOM 요소는 자체 속성이 없어 항상 비어 있다고 나온다.
		$c.util.onUploadClick(mpd_attach);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL52100.btn_file_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_goList_onclick
 * @author Inswave
 * @date 2026. 08. 14
 * @description 목록 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_goList_onclick = function (e) {
	try {
		$c.win.moveUrl("/ui/sample/template/ULDFIL59400.xml", {});
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL52100.btn_goList_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 08. 14
 * @description 저장 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_save_onclick = async function (e) {
	try {
		await scwin.save();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDFIL52100.btn_save_onclick" });
	}
};

/**
 * @event
 * @name scwin.mpd_attach_onComplete
 * @author Inswave
 * @date 2026. 08. 14
 * @description 파일 업로드 및 저장 완료. 안내 후 목록으로 이동한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.mpd_attach_onComplete = function (data) {
	try {
		$c.win.alert($c.data.getMessage("com_complete_0150", "저장"), () => { scwin.btn_goList_onclick(); });
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL52100.mpd_attach_onComplete" });
	}
};

/**
 * @event
 * @name scwin.mpd_attach_onerror
 * @author Inswave
 * @date 2026. 08. 14
 * @description 파일 업로드 실패
 * @param
 * @returns
 * @hidden N
*/
scwin.mpd_attach_onerror = function (data) {
	try {
		$c.win.alert($c.data.getMessage("com_complete_0151", "저장"));
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL52100.mpd_attach_onerror" });
	}
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 08. 14
 * @description 상세를 조회해 dma_detail 에 담는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, ref, target
 * @param
 * @returns
 * @hidden N
*/
scwin.selectDetail = async function () {
	dma_search.set("aplcNo", scwin.aplcNo);

	const sbmOptions = {
		id : "sbm_selectDetail",
		method : "get",
		action : "/api/listing/listinvstg/prtdepo-disposal/select-one",
		ref : "dma_search",
		target : "dma_detail=body",
		isProcessMsg : false
	};

	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	// 여기서 잡지 않으므로 오류가 나면 아래 처리는 실행되지 않는다.
	const result = await $c.sbm.executeDynamic(sbmOptions);

	// 조회 결과 처리는 submitDoneHandler 옵션 대신 여기서 직접 부른다.
	// 옵션으로 넘기면 await 가 풀린 뒤에 돌아 이어지는 코드와 순서가 어긋난다.
	scwin.sbm_selectDetail_submitdone(result);
};

/**
 * @method
 * @name scwin.sbm_selectDetail_submitdone
 * @author Inswave
 * @date 2026. 08. 14
 * @description 상세 조회 완료. 응답을 화면에 반영한다.
 *
 * 입력 컴포넌트를 dma_detail 에 ref 로 묶어 두면 target 바인딩만으로 화면이 채워진다.
 * 여기서는 ref 로 처리되지 않는 것만 손으로 넣는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_selectDetail_submitdone = function (e) {
	// 라디오·체크박스처럼 ref 로 값이 안 붙는 컴포넌트는 직접 넣는다.
	chk_reopnYn.setValue(dma_detail.get("reopnYn"));

	// 재보유 여부에 맞춰 일자 입력칸을 열고 닫는다.
	scwin.setReopnInput(dma_detail.get("reopnYn"));

	// 최종 주식수는 최초에서 처분을 뺀 값이다. 조회 직후에도 맞춰 둔다.
	scwin.calcLastShares();
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 08. 14
 * @description 검증 후 첨부파일과 함께 저장한다. 신규·수정은 action 만 다르다.
 *
 * multiupload 로 보내면 파일과 입력값이 한 번에 전송된다.
 * 첨부가 없는 화면이면 이 함수 대신 executeDynamic 으로 dma_detail 을 그대로 보내면 된다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - setParam 으로 넘길 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
	if (!await scwin.validate()) return;

	if (!await $c.win.confirm($c.data.getMessage("com_crud_0198", "저장"))) return;

	// 왼쪽 이름이 서버가 받는 항목명이다. 화면 id 가 아니라 전문 규격을 그대로 적는다.
	// 숫자 항목은 콤마를 뗀 값으로 보낸다. 화면에 보이는 "1,000" 을 그대로 보내면 서버에서 형변환이 깨진다.
	const params = [
		["prtdepoId", scwin.aplcNo],
		["shrhdNm", dma_detail.get("shrhdNm")],
		["fstPrtdepoShrs", scwin.toNumber(dma_detail.get("fstShrs"))],
		["prtdepoWithdShrs", scwin.toNumber(dma_detail.get("withdShrs"))],
		["prtdepoWithdRsn", dma_detail.get("withdRsn")],
		["prtdepoReopnYn", chk_reopnYn.getValue()],
		["prtdepoReopnDd", dma_detail.get("reopnDd")],
		["lstPrtdepoShrs", scwin.toNumber(dma_detail.get("lstShrs"))],
		["regId", $c.session.getUserInfo("integUsrId")]
	];

	mpd_attach.changeAction(scwin.isNewMode() ? "/api/listing/listinvstg/prtdepo-disposal/create" : "/api/listing/listinvstg/prtdepo-disposal/modify");

	params.forEach((param, index) => {
		mpd_attach.setParam(index, param[0], param[1]);
	});

	mpd_attach.startUpload();
};

/**
 * @event
 * @name scwin.mpd_attach_selectCallback
 * @author Inswave
 * @date 2026. 08. 14
 * @description 파일 선택 시 파일명을 입력칸에 표시한다.
 * 여러 첨부 항목이 하나의 multiupload 를 공유하므로 uploadTarget 으로 대상을 가른다.
 * @param
 * @returns
 * @hidden N
*/
scwin.mpd_attach_selectCallback = function (fileInfoArr) {
	const fileInfos = mpd_attach.getFileInfos();

	if ($c.util.isEmpty(fileInfos)) return;

	// 방금 추가된 파일은 항상 목록의 마지막이다.
	const fileName = fileInfos[fileInfos.length - 1].name;

	// 어느 항목의 파일인지 기억해 둔 값으로 넣을 곳을 정한다.
	dma_detail.set(scwin.uploadTarget, fileName);
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 08. 14
 * @description 저장 전 입력값을 검증한다. 첫 번째 오류에서 멈추고 그 항목에 포커스를 준다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - requiredList 의 항목, 그 아래 업무 규칙 검증
 * @param
 * @returns
 * @hidden N
*/
scwin.validate = async function () {
	/* 필수·자리수·형식 검증은 공통함수 $c.data.validateGroup 을 쓴다.
	 * 직접 for 문을 돌며 isEmpty 를 확인하지 않는다. 안내 문구와 포커스 이동까지
	 * 공통함수가 처리하므로 화면마다 같은 코드를 반복할 필요가 없다.
	 *
	 * id 는 그룹 안 컴포넌트가 ref 로 묶인 DataCollection 컬럼 아이디를 쓴다.
	 * label 을 생략하면 dataMap 의 name 을 안내 문구에 쓴다.
	 *
	 * 쓸 수 있는 옵션 : mandatory, minLength, minByteLength, isEmail, isPhone, valFunc
	 */
	const valInfo = [
		{ id : "corpNm", mandatory : true },
		{ id : "shrhdNm", mandatory : true },
		{ id : "withdShrs", mandatory : true },
		{ id : "withdRsn", mandatory : true }
	];

	if (!await $c.data.validateGroup(grp_form, valInfo)) return false;

	// 공통함수로 표현할 수 없는 업무 규칙만 여기에 이어서 쓴다.
	const withdShrs = scwin.toNumber(dma_detail.get("withdShrs"));
	const fstShrs = scwin.toNumber(dma_detail.get("fstShrs"));

	if (withdShrs <= 0) {
		await $c.win.alert("처분 주식수는 0보다 커야 합니다.");
		ipt_withdShrs.focus();
		return false;
	}

	// 가진 것보다 많이 처분할 수는 없다.
	if (withdShrs > fstShrs) {
		await $c.win.alert("처분 주식수가 최초 주식수보다 많습니다.");
		ipt_withdShrs.focus();
		return false;
	}

	// 재보유를 고르면 일자를 반드시 넣어야 한다.
	if (chk_reopnYn.getValue() === "Y" && $c.util.isEmpty(dma_detail.get("reopnDd"))) {
		await $c.win.alert($c.data.getMessage("com_crud_0199", "재보유 일자"));
		cal_reopnDd.focus();
		return false;
	}

	return true;
};

/**
 * @method
 * @name scwin.toNumber
 * @author Inswave
 * @date 2026. 08. 14
 * @description 천단위 콤마가 섞인 문자열을 숫자로 바꾼다. 값이 없으면 0 을 반환한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.toNumber = function (value) {
	if ($c.util.isEmpty(value)) return 0;

	return $c.num.unFormatNumber(value);
};
